begin;

-- Orthodox Autocephalous Church of Albania calendar 2026.
-- Source: https://orthodoxalbania.org/2026/kalendari-kishtar/
-- JSON data: https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/{month}.json?v=0.5.536

delete from public.calendar_day_translations t
using public.calendar_days d
where t.calendar_day_id = d.id
  and d.country_code = 'AL'
  and d.calendar_code = 'al-orthodox-autocephalous-church'
  and d.calendar_date between date '2026-01-01' and date '2026-12-31';

delete from public.calendar_days
where country_code = 'AL'
  and calendar_code = 'al-orthodox-autocephalous-church'
  and calendar_date between date '2026-01-01' and date '2026-12-31';

insert into public.calendar_days (
  country_code, language_code, calendar_code, calendar_date,
  feast_rank, saints, title, details, fasting_note,
  editorial_source, is_published
) values
('AL','sq','al-orthodox-autocephalous-church','2026-01-01','cruce roșie',array[]::text[],'Rrethprerja në mish e Zotit, Perëndisë dhe Shpëtimtarit tonë Jisu Krisht; Vasili i Madh, kryepiskop i Qesarisë; Emelia, nëna e shën Vasilit; Theodhoti, martir; Grigori, episkop i Nazianzit; Telemaku (ose Almaki), martir; Theodhosi, igumen i Triglias në Bitini; Petro i Peloponezit, neomartir; Fulgenti, episkop i Ruspit','Rrethprerja në mish e Zotit, Perëndisë dhe Shpëtimtarit tonë Jisu Krisht; Vasili i Madh, kryepiskop i Qesarisë; Emelia, nëna e shën Vasilit; Theodhoti, martir; Grigori, episkop i Nazianzit; Telemaku (ose Almaki), martir; Theodhosi, igumen i Triglias në Bitini; Petro i Peloponezit, neomartir; Fulgenti, episkop i Ruspit | Hahen të gjitha | Epistle: Kol. 2:8-12 | Gospel: Llk. 2:20-21, 40-52','Hahen të gjitha','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-02','cruce neagră',array[]::text[],'Silvestri, papë i Romës; Theagjeni, episkop i Parionit, hieromartir; Theopempti; Theodhota, nëna e anargjendëve të shenjtë Kozma dhe Damian; Mark Shurdhi, oshënar; Sergji, martir; Theopisti, martir; Nili i Shenjtëruar, themelues i manastirit të Gjeromerionit, oshënar; Kozmai I, patriark i Konstandinopojës; Gjergj Gjeorgjiani, neomartir; Serafimi i Sarovit, oshënar; Silvestri i Shpellave të Kievit, oshënar; Juliana Lazarevskaja, oshënare','Silvestri, papë i Romës; Theagjeni, episkop i Parionit, hieromartir; Theopempti; Theodhota, nëna e anargjendëve të shenjtë Kozma dhe Damian; Mark Shurdhi, oshënar; Sergji, martir; Theopisti, martir; Nili i Shenjtëruar, themelues i manastirit të Gjeromerionit, oshënar; Kozmai I, patriark i Konstandinopojës; Gjergj Gjeorgjiani, neomartir; Serafimi i Sarovit, oshënar; Silvestri i Shpellave të Kievit, oshënar; Juliana Lazarevskaja, oshënare | Epistle: Heb. 11:8-16 [J.30] | Gospel: Jn. 3:1-15',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-03','cruce neagră',array[]::text[],'Malakia, profet; Gordi i Qesarisë, martir; Një nënë dhe dy fëmijët e saj, martirë; Petro i Atroas, oshënar; Thomaidha e Lesbosit, oshënare; Akaqi i Latros, oshënar; Gjinovefa e Parisit','Malakia, profet; Gordi i Qesarisë, martir; Një nënë dhe dy fëmijët e saj, martirë; Petro i Atroas, oshënar; Thomaidha e Lesbosit, oshënare; Akaqi i Latros, oshënar; Gjinovefa e Parisit | Epistle: 1 Tim. 3:13-4:5 | Gospel: Mt. 3:1-6',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-04','cruce neagră',array[]::text[],'Sinaksi/Mbledhja e të Shtatëdhjetë Apostujve; Zosimai dhe Athanasi, martirë; Krisanthi dhe Efimia, martirë; Joan Shkollari, oshënar; Gjashtë martirët; Apolinaria-Dorotheu, oshënare; Theoktisti, igumen i Manastirit të Kukumios në Sicili, oshënar; Efthimi i Ri, oshënar; Efthimi i Vatopedit dhe 12 murgjit e tij, martirë; Onufri, neomartir; Efstathi, kryepiskop i Serbisë','Sinaksi/Mbledhja e të Shtatëdhjetë Apostujve; Zosimai dhe Athanasi, martirë; Krisanthi dhe Efimia, martirë; Joan Shkollari, oshënar; Gjashtë martirët; Apolinaria-Dorotheu, oshënare; Theoktisti, igumen i Manastirit të Kukumios në Sicili, oshënar; Efthimi i Ri, oshënar; Efthimi i Vatopedit dhe 12 murgjit e tij, martirë; Onufri, neomartir; Efstathi, kryepiskop i Serbisë | Epistle: 2 Tim. 4:5-8 | Gospel: Mk. 1:1-8',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-05','cruce neagră',array[]::text[],'Vigjilja e Theofanisë; Theopempti dhe Theonai, martirë; Singlitikia, oshënare; Grigori i Akritës, oshënar; Fostiri, oshënar; Mina Sinaiti, oshënar; Saisi, martir; Theoidhosi, martir; Domnina, oshënare; Tatjana, oshënare; Romanoi i Karpenisionit, neomartir','Vigjilja e Theofanisë; Theopempti dhe Theonai, martirë; Singlitikia, oshënare; Grigori i Akritës, oshënar; Fostiri, oshënar; Mina Sinaiti, oshënar; Saisi, martir; Theoidhosi, martir; Domnina, oshënare; Tatjana, oshënare; Romanoi i Karpenisionit, neomartir | Kreshmë e rreptë. Orët e mëdha | Epistle: 2 Tim. 4:5-8 | Gospel: Mk. 1:1-8','Kreshmë e rreptë. Orët e mëdha','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-06','cruce roșie',array[]::text[],'Pagëzimi (Theofania) i Zotit, Perëndisë dhe Shpëtimtarit tonë Jisu Krisht; Romanoi i Lakedhemonisë (Spartë), neomartir','Pagëzimi (Theofania) i Zotit, Perëndisë dhe Shpëtimtarit tonë Jisu Krisht; Romanoi i Lakedhemonisë (Spartë), neomartir | Bekimi i madh i ujit. Hahen të gjitha | Epistle: Tit. 2:11-14, 3:4-7 | Gospel: Mt. 3:13-17','Bekimi i madh i ujit. Hahen të gjitha','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-07','cruce neagră',array[]::text[],'Mbledhja (Sinaksi) e Joan Pagëzorit; Transferimi i lipsanit të shenjtë të dorës së djathtë të Pararendësit në Konstandinopojë; Athanasi i Atalias, neomartir; Sidi, ava i Lastingamit, oshënar','Mbledhja (Sinaksi) e Joan Pagëzorit; Transferimi i lipsanit të shenjtë të dorës së djathtë të Pararendësit në Konstandinopojë; Athanasi i Atalias, neomartir; Sidi, ava i Lastingamit, oshënar | Epistle: Vep. 19:1-8 | Gospel: Jn. 1:29-34','Fish permitted','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-08','cruce neagră',array[]::text[],'Domnika, oshënare; Gjergj Hozeviti, oshënar; Karteri i Qesarisë, hieromartir; Theofili dhe Eladhi, martirë; Agathoni, oshënar; Shemaja Elamiti, profet; Atiku, patriark i Konstandinopojës; Kiri, patriark i Konstandinopojës; Theodhori, themelues i Manastirit të Koras, oshënar; Makar Makris, igumen i Manastirit të Krishtit Pantokrator; Abo i Tbilisit/Tiflisit, martir; Grigori i Shpellave të Kievit, oshënar; Grigor Çudibërësi në Lavrën e Shpellave të Kievit, oshënar; Grigori, episkop i Ohrit; Isidori i Jurevit, hieromartir, dhe 72 shokët e tij; Severini, apostull i Norikut','Domnika, oshënare; Gjergj Hozeviti, oshënar; Karteri i Qesarisë, hieromartir; Theofili dhe Eladhi, martirë; Agathoni, oshënar; Shemaja Elamiti, profet; Atiku, patriark i Konstandinopojës; Kiri, patriark i Konstandinopojës; Theodhori, themelues i Manastirit të Koras, oshënar; Makar Makris, igumen i Manastirit të Krishtit Pantokrator; Abo i Tbilisit/Tiflisit, martir; Grigori i Shpellave të Kievit, oshënar; Grigor Çudibërësi në Lavrën e Shpellave të Kievit, oshënar; Grigori, episkop i Ohrit; Isidori i Jurevit, hieromartir, dhe 72 shokët e tij; Severini, apostull i Norikut | Epistle: Jak. 1:19-27 [J.31] | Gospel: Jn. 3:22-33',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-09','cruce neagră',array[]::text[],'Poliefkti, martir; Efstrat Çudibërësi, igumen i Manastirit të Agaurëve, oshënar; Petro II, episkop i Sevastisë; Andonia e Nikomedisë, martire; Laurenti, martir; Parthena e Edesës, neomartire; Filipi, mitropolit i Moskës, martir','Poliefkti, martir; Efstrat Çudibërësi, igumen i Manastirit të Agaurëve, oshënar; Petro II, episkop i Sevastisë; Andonia e Nikomedisë, martire; Laurenti, martir; Parthena e Edesës, neomartire; Filipi, mitropolit i Moskës, martir | Epistle: Jak. 2:1-13 | Gospel: Mk. 1:9-15',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-10','cruce neagră',array[]::text[],'Grigori, episkop i Nisës; Theosevia, bashkëshortja e shën Grigorit të Nisës; Dometiani, episkop i Melitinës; Markian Ekonomi i Kishës së Madhe; Amuni i Nitrisë, oshënar; Pavli, themelues i manastirit të Obnorës, oshënar; Makari i Pismas, oshënar; Theofani i Mbylluri, episkop i Tambovit dhe i Vladimirit; Antipa Hezikasti, oshënar','Grigori, episkop i Nisës; Theosevia, bashkëshortja e shën Grigorit të Nisës; Dometiani, episkop i Melitinës; Markian Ekonomi i Kishës së Madhe; Amuni i Nitrisë, oshënar; Pavli, themelues i manastirit të Obnorës, oshënar; Makari i Pismas, oshënar; Theofani i Mbylluri, episkop i Tambovit dhe i Vladimirit; Antipa Hezikasti, oshënar | Epistle: Efes. 6:10-17 | Gospel: Mt. 4:1-11',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-11','cruce neagră',array[]::text[],'Theodhos Kinovjarku, oshënar; Theodhori dhe Agapi, oshënarë; Mairi, martir; Vitali, oshënar; Theodhosi, igumen i manastirit të Filotheut dhe episkop i Trebizondës; Mihaili i Klopsit, i marrë për Krishtin','Theodhos Kinovjarku, oshënar; Theodhori dhe Agapi, oshënarë; Mairi, martir; Vitali, oshënar; Theodhosi, igumen i manastirit të Filotheut dhe episkop i Trebizondës; Mihaili i Klopsit, i marrë për Krishtin | Epistle: 2 Kor. 4:6-15 | Gospel: Mt. 4:12-17',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-12','cruce neagră',array[]::text[],'Tatiana e Romës, martire; Merki, martir; Tetë martirët e Nikeas; Efthasia, martire; Ilia Çudibërësi, oshënar; Filotheu i Antiokisë, martir; Martiniani i Liqenit të Bardhë, oshënar; Galaktioni, dishepull i shën Martinianit, oshënar','Tatiana e Romës, martire; Merki, martir; Tetë martirët e Nikeas; Efthasia, martire; Ilia Çudibërësi, oshënar; Filotheu i Antiokisë, martir; Martiniani i Liqenit të Bardhë, oshënar; Galaktioni, dishepull i shën Martinianit, oshënar | Epistle: Efes. 4:7-13 | Gospel: Jn. 10:39-42',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-13','cruce neagră',array[]::text[],'Ermili dhe Stavroniku, martirë; Jakovi, episkop i Nisibit; Athanasi, martir; Pahomi dhe Papirini, martirë; Maksim Kafsokaliviti, oshënar; Irinarku i Rostovit, oshënar; Eleazari i Anzherskut, oshënar; Ilari, episkop i Puatjerit','Ermili dhe Stavroniku, martirë; Jakovi, episkop i Nisibit; Athanasi, martir; Pahomi dhe Papirini, martirë; Maksim Kafsokaliviti, oshënar; Irinarku i Rostovit, oshënar; Eleazari i Anzherskut, oshënar; Ilari, episkop i Puatjerit | Epistle: Vep. 16:16-34 | Gospel: Llk. 20:1-8',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-14','cruce neagră',array[]::text[],'Mbyllja e Theofanisë dhe etërit që u masakruan në malin Sina; 43 etërit që u masakruan në Raitho; Theodhuli, oshënar; Anjeza, martire; Stefani i Kenolakos, oshënar; Nino (Nina) e Gjeorgjisë, oshënare; Sava, kryepiskop i parë i Serbisë dhe themelues i manastirit të Hilandarit','Mbyllja e Theofanisë dhe etërit që u masakruan në malin Sina; 43 etërit që u masakruan në Raitho; Theodhuli, oshënar; Anjeza, martire; Stefani i Kenolakos, oshënar; Nino (Nina) e Gjeorgjisë, oshënare; Sava, kryepiskop i parë i Serbisë dhe themelues i manastirit të Hilandarit | Epistle: Rom. 5:1-10 | Gospel: Mt. 6:22-33',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-15','cruce neagră',array[]::text[],'Pavli i Tebës, oshënar; Joan Kaliviti, oshënar; Pansofi i Aleksandrisë, martir; Gjashtë murgjit në shkretëtirë; Gavrieli i Lesnovos, oshënar; Prohori i Vranskit, oshënar; Mauri, dishepull i shën Benediktit, oshënar','Pavli i Tebës, oshënar; Joan Kaliviti, oshënar; Pansofi i Aleksandrisë, martir; Gjashtë murgjit në shkretëtirë; Gavrieli i Lesnovos, oshënar; Prohori i Vranskit, oshënar; Mauri, dishepull i shën Benediktit, oshënar | Epistle: Rom. 10:1-10 | Gospel: Mt. 8:28-9:1',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-16','cruce neagră',array[]::text[],'Zinxhirët e shën Petros; Spevsipi, Elevsipi, Melevsipi dhe Neonila, martirë; Junila, martire; Danakt Lexuesi, martir; Damaskini, hieromartir i ri; Maksimi i Totmës (Vologda), i marrë për Krishtin; (Romili, Nestori, Martini, Danieli, Sisoi, Zosimai dhe Grigori); Honorati, episkop i Arlës dhe themelues i manastirit të Lerinsit','Zinxhirët e shën Petros; Spevsipi, Elevsipi, Melevsipi dhe Neonila, martirë; Junila, martire; Danakt Lexuesi, martir; Damaskini, hieromartir i ri; Maksimi i Totmës (Vologda), i marrë për Krishtin; (Romili, Nestori, Martini, Danieli, Sisoi, Zosimai dhe Grigori); Honorati, episkop i Arlës dhe themelues i manastirit të Lerinsit | Epistle: Vep. 12:1-11 | Gospel: Mt. 22:35-46','Oil and wine','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-17','cruce neagră',array[]::text[],'Andoni i Madh, oshënar; Theodhosi i Madh, perandor; Akili (Akilai), oshënar; Andoni i Ri i Verias, oshënar; Gjergji i Janinës, neomartir; Makari (Kalogjeras) i Patmosit, oshënar; Andon Romaku, oshënar; Andoni i Dimkut, oshënar; Andoni në Krasnij hollm, oshënar; Andon Çjornoozjerskij, oshënar; Andoni i Vologdës, oshënar','Andoni i Madh, oshënar; Theodhosi i Madh, perandor; Akili (Akilai), oshënar; Andoni i Ri i Verias, oshënar; Gjergji i Janinës, neomartir; Makari (Kalogjeras) i Patmosit, oshënar; Andon Romaku, oshënar; Andoni i Dimkut, oshënar; Andoni në Krasnij hollm, oshënar; Andon Çjornoozjerskij, oshënar; Andoni i Vologdës, oshënar | Epistle: Heb. 13:17-21 | Gospel: Llk. 6:17-23',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-18','cruce neagră',array[]::text[],'Athanasi dhe Kirili, patriarkë të Aleksandrisë; Theodhula, Eladhi, Voithi, Evagri dhe Makari, martirë; Kseni, martire; Efremi, episkop i Melasonit; Maksimi, princ i Serbisë dhe mitropolit i Hungro-Valahisë; Athanasi, themelues i manastirit të Siademskut, oshënar','Athanasi dhe Kirili, patriarkë të Aleksandrisë; Theodhula, Eladhi, Voithi, Evagri dhe Makari, martirë; Kseni, martire; Efremi, episkop i Melasonit; Maksimi, princ i Serbisë dhe mitropolit i Hungro-Valahisë; Athanasi, themelues i manastirit të Siademskut, oshënar | Epistle: Heb. 13:7-16 | Gospel: Llk. 17:12-19',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-19','cruce neagră',array[]::text[],'Makari i Madh, i quajtur Egjiptiani, oshënar; Makari i Aleksandrisë, i quajtur Qytetari, oshënar; Efrasia e Nikomedisë, martire; Arseni, kryepiskop i Korfuzit; Melet Konfesori, murg në malin Galezion; Mark Evgjeniku, mitropolit i Efesit; Andon Ravai Koresiti, martir; Mrekullia e shën Vasili të Madh në Nikea; Transferimi i lipsaneve të shën Grigor Theologut; Makari i Lavrës së Shpellave të Kievit, oshënar; Makari, dhjak në Lavrën e Shpellave të Kievit, oshënar; Andoni i Gjeorgjisë, oshënar; Theodhori i Novgorodit, i marrë për Krishtin; Makar Romaku, oshënar','Makari i Madh, i quajtur Egjiptiani, oshënar; Makari i Aleksandrisë, i quajtur Qytetari, oshënar; Efrasia e Nikomedisë, martire; Arseni, kryepiskop i Korfuzit; Melet Konfesori, murg në malin Galezion; Mark Evgjeniku, mitropolit i Efesit; Andon Ravai Koresiti, martir; Mrekullia e shën Vasili të Madh në Nikea; Transferimi i lipsaneve të shën Grigor Theologut; Makari i Lavrës së Shpellave të Kievit, oshënar; Makari, dhjak në Lavrën e Shpellave të Kievit, oshënar; Andoni i Gjeorgjisë, oshënar; Theodhori i Novgorodit, i marrë për Krishtin; Makar Romaku, oshënar | Epistle: 1 Kor. 16:13-24 | Gospel: Mt. 22:2-14',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-20','cruce neagră',array[]::text[],'Efthimi i Madh, oshënar; Vasi, Eusebi, Eftiki dhe Vasiliadhi, martirë; Inai, Rimai dhe Pinai, martirë; Petro, mbledhës i taksave; Ana e Romës, martire; Tirsi dhe Agna, martirë; Leoni I Thrakasi, perandor; Zaharia, neomartir; Laurenti i Mbyllur i Shpellave të Kievit, oshënar; Efthimi i Shpellave të Kievit, oshënar; Efthimi, themelues i manastirit të Sianzhemskut, oshënar; Efthimi i Tirnovos, patriark i Bullgarisë; Theodhor (Kuzmiçi), ish-cari Aleksandri I, oshënar','Efthimi i Madh, oshënar; Vasi, Eusebi, Eftiki dhe Vasiliadhi, martirë; Inai, Rimai dhe Pinai, martirë; Petro, mbledhës i taksave; Ana e Romës, martire; Tirsi dhe Agna, martirë; Leoni I Thrakasi, perandor; Zaharia, neomartir; Laurenti i Mbyllur i Shpellave të Kievit, oshënar; Efthimi i Shpellave të Kievit, oshënar; Efthimi, themelues i manastirit të Sianzhemskut, oshënar; Efthimi i Tirnovos, patriark i Bullgarisë; Theodhor (Kuzmiçi), ish-cari Aleksandri I, oshënar | Epistle: 2 Kor. 4:6-15 | Gospel: Llk. 6:17-23',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-21','cruce neagră',array[]::text[],'Maksim Konfesori; Neofiti i Nikeas, martir; Zosimai i Sirakuzës, oshënar; Evgjeni, Valeriani, Kandidi dhe Akuila i Trapezundës, martirë; Agnia e Romës, martire; Katër martirët e Tirit; Neofiti i Vatopedhit, oshënar; Maksim Greku, oshënar','Maksim Konfesori; Neofiti i Nikeas, martir; Zosimai i Sirakuzës, oshënar; Evgjeni, Valeriani, Kandidi dhe Akuila i Trapezundës, martirë; Agnia e Romës, martire; Katër martirët e Tirit; Neofiti i Vatopedhit, oshënar; Maksim Greku, oshënar | Epistle: 2 Kor. 1:21-2:4 | Gospel: Mt. 22:2-14',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-22','cruce neagră',array[]::text[],'Timotheu, apostull; Anastas Persiani, martir; Manueli, Gjergji, Petro, Leoni, hieromartirë; dhe shokët e tyre, martirë; Josif Kretasi, i Shenjtëruari, i quajtur edhe Samako, oshënar; Anastasi i Lavrës së Kievit, oshënar; Makar Çudibërësi, igumen i manastirit të Zhabinit, oshënar','Timotheu, apostull; Anastas Persiani, martir; Manueli, Gjergji, Petro, Leoni, hieromartirë; dhe shokët e tyre, martirë; Josif Kretasi, i Shenjtëruari, i quajtur edhe Samako, oshënar; Anastasi i Lavrës së Kievit, oshënar; Makar Çudibërësi, igumen i manastirit të Zhabinit, oshënar | Epistle: 2 Tim. 1:3-9 | Gospel: Mt. 25:14-30',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-23','cruce neagră',array[]::text[],'Klementi, episkop i Angjirës, dhe Agathangjeli, martir; Dy martirët e Pariosit; Eusebi, oshënar; Maisima Siriani, oshënar; Salaman Hezikasti, oshënar; Dionisi i Olimpit, oshënar; Genadi i Kostromës, oshënar','Klementi, episkop i Angjirës, dhe Agathangjeli, martir; Dy martirët e Pariosit; Eusebi, oshënar; Maisima Siriani, oshënar; Salaman Hezikasti, oshënar; Dionisi i Olimpit, oshënar; Genadi i Kostromës, oshënar | Epistle: Efes. 2:4-10 | Gospel: Llk. 10:25-37','Oil and wine','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-24','cruce neagră',array[]::text[],'Kseni, oshënare, dhe dy shërbëtoret e saj; Pavli, Pavsirioni dhe Theodhotioni, martirë; Vavila, Agapi dhe Timotheu, martirë; Makedoni, oshënar; Filoni, episkop i Karpasias në Qipro; Zosimai, oshënar; Hermogjeni dhe Mamasi (ose Minai), martirë; Filipiku (ose Filipi), prift; Varsimai, martir; Krisoploki, martire; Transferimi i lipsanit të shën Anastas Persianit; Neofiti i Mbyllur, oshënar; Kseni e Shën Petërburgut, oshënare; Joani i Kazanit, martir; Gjerasimi, episkop i Permit','Kseni, oshënare, dhe dy shërbëtoret e saj; Pavli, Pavsirioni dhe Theodhotioni, martirë; Vavila, Agapi dhe Timotheu, martirë; Makedoni, oshënar; Filoni, episkop i Karpasias në Qipro; Zosimai, oshënar; Hermogjeni dhe Mamasi (ose Minai), martirë; Filipiku (ose Filipi), prift; Varsimai, martir; Krisoploki, martire; Transferimi i lipsanit të shën Anastas Persianit; Neofiti i Mbyllur, oshënar; Kseni e Shën Petërburgut, oshënare; Joani i Kazanit, martir; Gjerasimi, episkop i Permit | Epistle: 1 Tim. 6:11-16 | Gospel: Llk. 20:46-21:4',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-25','cruce neagră',array[]::text[],'Grigor Theologu, kryepiskop i Konstandinopojës; Medula dhe shokët e saj, martirë; Kastini, episkop i Bizantit; Dhimitër Skevofilaksi, oshënar; Publi, oshënar; Marisi, oshënar; Apollo, oshënar; Afksenti, neomartir; Moisiu, kryepiskop i Novgorodit; Vladimiri i Kievit dhe Beniamini i Petrogradit, hieromartirë; Elisabeta, martire; Sinaksi i gjithë Martirëve të Rinj të Kishës Ruse të shek. XX; Aleksandër Hotovicki, hieromartir','Grigor Theologu, kryepiskop i Konstandinopojës; Medula dhe shokët e saj, martirë; Kastini, episkop i Bizantit; Dhimitër Skevofilaksi, oshënar; Publi, oshënar; Marisi, oshënar; Apollo, oshënar; Afksenti, neomartir; Moisiu, kryepiskop i Novgorodit; Vladimiri i Kievit dhe Beniamini i Petrogradit, hieromartirë; Elisabeta, martire; Sinaksi i gjithë Martirëve të Rinj të Kishës Ruse të shek. XX; Aleksandër Hotovicki, hieromartir | Epistle: Heb. 7:26-8:2 | Gospel: Llk. 19:1-10',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-26','cruce neagră',array[]::text[],'Ksenofonti, Maria, Arkadi dhe Joani, oshënarë; Simeoni i Vjetër, oshënar; Anania, prift; Petro dhe shtatë ushtarë, martirë; Amonai i Egjiptit, oshënar; Gabrieli i Jerusalemit, oshënar; Dy Martirët e Frigjisë; Klementi i malit Sagmata, oshënar; Transferimi i Lipsaneve të Etërve tanë të shenjtë Theodhor Studiti dhe Josifi i Selanikut; Davidi III Restauruesi, mbret i Gjeorgjisë; Paula e Romës, oshënare','Ksenofonti, Maria, Arkadi dhe Joani, oshënarë; Simeoni i Vjetër, oshënar; Anania, prift; Petro dhe shtatë ushtarë, martirë; Amonai i Egjiptit, oshënar; Gabrieli i Jerusalemit, oshënar; Dy Martirët e Frigjisë; Klementi i malit Sagmata, oshënar; Transferimi i Lipsaneve të Etërve tanë të shenjtë Theodhor Studiti dhe Josifi i Selanikut; Davidi III Restauruesi, mbret i Gjeorgjisë; Paula e Romës, oshënare | Epistle: Rom. 12:6-14 | Gospel: Llk. 18:18-27',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-27','cruce neagră',array[]::text[],'Transferimi i lipsaneve të shën Joan Gojartit; Markiana, perandoreshë; Klaudiani, oshënar; Petro Egjiptiani, oshënar; Dhimitri, neomartir; Titi Ushtari i Shpellave të Kievit, oshënar','Transferimi i lipsaneve të shën Joan Gojartit; Markiana, perandoreshë; Klaudiani, oshënar; Petro Egjiptiani, oshënar; Dhimitri, neomartir; Titi Ushtari i Shpellave të Kievit, oshënar | Epistle: Heb. 7:26-8:2 | Gospel: Jn. 10:9-16',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-28','cruce neagră',array[]::text[],'Efrem Siriani, oshënar; Palad Anakoreti, oshënar; Jakov Asketi, oshënar; Dy martiret; Harisa, martire; Isaak Siriani, oshënar; Efrem Eunuku i Shpellave të Kievit, episkop i Perejaslavit; Efremi i Novotorzhskut, oshënar; Theodhosi i Totmës, oshënar; Joani i Reomesë, oshënar','Efrem Siriani, oshënar; Palad Anakoreti, oshënar; Jakov Asketi, oshënar; Dy martiret; Harisa, martire; Isaak Siriani, oshënar; Efrem Eunuku i Shpellave të Kievit, episkop i Perejaslavit; Efremi i Novotorzhskut, oshënar; Theodhosi i Totmës, oshënar; Joani i Reomesë, oshënar | Epistle: Rom. 15:1-7 | Gospel: Mt. 15:21-28',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-29','cruce neagră',array[]::text[],'Transferimi i lipsanit të shën Ignat Hyjmbajtësit; Hiperekio, Filotheu, Jakovi, Abibi, Juliani, Romani dhe Parigori, martirë; Silvani, episkop i Emesës; Llukai, dhjak; dhe Moki, lexues; Sarveli dhe Vivaja e Edesës, martirë; Varsime Rrëfyesi, episkop i Edhesës; Afrahat Persiani, oshënar; Akepsimi, oshënar; Dhimitri i Hios, neomartir; Laurenti i Kievit, oshënar; Gjerasimi, Pitirimi dhe Jonai, episkopë të Permit','Transferimi i lipsanit të shën Ignat Hyjmbajtësit; Hiperekio, Filotheu, Jakovi, Abibi, Juliani, Romani dhe Parigori, martirë; Silvani, episkop i Emesës; Llukai, dhjak; dhe Moki, lexues; Sarveli dhe Vivaja e Edesës, martirë; Varsime Rrëfyesi, episkop i Edhesës; Afrahat Persiani, oshënar; Akepsimi, oshënar; Dhimitri i Hios, neomartir; Laurenti i Kievit, oshënar; Gjerasimi, Pitirimi dhe Jonai, episkopë të Permit | Epistle: 1 Kor. 15:1-11 | Gospel: Llk. 18:35-43',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-30','cruce neagră',array[]::text[],'Tre Hierarkët: Vasili i Madh, Grigor Theologu dhe Joan Gojarti; Ilopoliti i Romës, hieromartir, dhe shokët e tij: Censorini, Sabini, Krisa (ose Aura), Feliksi, Maksimi, Herkuli, Veneriusi, Stirakiusi, Minai, Komodi, Hermesi, Mauri, Eusebi, Rustiku, Monagri, Armandinusi, Olimpi, Qipro, Theodhori, Maksimi, Arkelau dhe Qirjako; Theofili i Ri, martir; Theodhori i Mitilinit, neomartir; Petro, mbret i Bullgarisë; Zenon Kreshmuesi i Lavrës së Shpellave të Kievit; Batilda, mbretëreshë e Francës','Tre Hierarkët: Vasili i Madh, Grigor Theologu dhe Joan Gojarti; Ilopoliti i Romës, hieromartir, dhe shokët e tij: Censorini, Sabini, Krisa (ose Aura), Feliksi, Maksimi, Herkuli, Veneriusi, Stirakiusi, Minai, Komodi, Hermesi, Mauri, Eusebi, Rustiku, Monagri, Armandinusi, Olimpi, Qipro, Theodhori, Maksimi, Arkelau dhe Qirjako; Theofili i Ri, martir; Theodhori i Mitilinit, neomartir; Petro, mbret i Bullgarisë; Zenon Kreshmuesi i Lavrës së Shpellave të Kievit; Batilda, mbretëreshë e Francës | Epistle: Heb. 13:7-16 | Gospel: Mt. 5:14-19','Oil and wine','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-01-31','cruce neagră',array[]::text[],'Kir dhe Joan, martirë dhe anargjendë; Athanasia, Theodhota, Theoktista dhe Evdhokia, martire; Viktorini, Viktori, Niqifori, Klaudi, Diodori, Serapioni dhe Papia, martirë; Trifena, martire; Athanasi, episkop i Methonës; Ilia Ardunis, neomartir; Nikita i Mbylluri i Shpellave të Kievit dhe episkop i Novgorodit; Pahomi, themelues i manastirit të Kienskut, oshënar; Markela, vejushë në Romë, oshënare','Kir dhe Joan, martirë dhe anargjendë; Athanasia, Theodhota, Theoktista dhe Evdhokia, martire; Viktorini, Viktori, Niqifori, Klaudi, Diodori, Serapioni dhe Papia, martirë; Trifena, martire; Athanasi, episkop i Methonës; Ilia Ardunis, neomartir; Nikita i Mbylluri i Shpellave të Kievit dhe episkop i Novgorodit; Pahomi, themelues i manastirit të Kienskut, oshënar; Markela, vejushë në Romë, oshënare | Epistle: 2 Tim. 2:11-19 [J.33] | Gospel: Llk. 18:2-8',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/january.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-02-01','cruce neagră',array[]::text[],'E Doganierit dhe Fariseut; Dësh. Trifoni; Trifon, martir; Saturi, Saturnini, Sekundi, Revokatusi, Perpetua dhe Felicitia, martirë; Petro në Galati, oshënar; Bendimiani, oshënar; Davidi, Simeoni dhe Gjergji i Mitilinit, oshënarë; Vasil Pohuesi, episkop i Selanikut; Nili i Ri, martir; Timothe Pohuesi; Theioni dhe dy fëmijët e tij, martirë; Karioni, martir; Anastasi, neomartir; Trifoni i Peçengës dhe Kollës, oshënar; Brixhida e Kildarës, oshënare','E Doganierit dhe Fariseut; Dësh. Trifoni; Trifon, martir; Saturi, Saturnini, Sekundi, Revokatusi, Perpetua dhe Felicitia, martirë; Petro në Galati, oshënar; Bendimiani, oshënar; Davidi, Simeoni dhe Gjergji i Mitilinit, oshënarë; Vasil Pohuesi, episkop i Selanikut; Nili i Ri, martir; Timothe Pohuesi; Theioni dhe dy fëmijët e tij, martirë; Karioni, martir; Anastasi, neomartir; Trifoni i Peçengës dhe Kollës, oshënar; Brixhida e Kildarës, oshënare | Nis Triodi | Epistle: Rom. 8:28-39 | Gospel: Llk. 18:10-14','Nis Triodi','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/february.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-02-02','cruce roșie',array[]::text[],'Paraqitja e Zotit Jisu Krisht në Tempull (Ipapandia); Agathodhori, martir; Jordani i Trebizondës, neomartir; Gavrili, neomartir','Paraqitja e Zotit Jisu Krisht në Tempull (Ipapandia); Agathodhori, martir; Jordani i Trebizondës, neomartir; Gavrili, neomartir | Epistle: Heb. 7:7-17 | Gospel: Llk. 2:22-40','Fish permitted','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/february.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-02-03','cruce neagră',array[]::text[],'Simeon Hyjpritësi; Pr/sha Ana; Nikolla i Japonisë; Adriani dhe Euvuli, martirë; Vlashi, martir; Azaria, profet; Pavli dhe Simoni, martirë; Klaudi, oshënar; Sava i Janinës, oshënar; Stamati, Joani dhe Nikolla, neomartirë; Nikolla, Kryepiskop i Japonisë; Simeoni, episkop i parë i Tverit; Romani, princ i Ugliçit; Ansgari, episkop i Hamburgut dhe apostull i Skandinavisë','Simeon Hyjpritësi; Pr/sha Ana; Nikolla i Japonisë; Adriani dhe Euvuli, martirë; Vlashi, martir; Azaria, profet; Pavli dhe Simoni, martirë; Klaudi, oshënar; Sava i Janinës, oshënar; Stamati, Joani dhe Nikolla, neomartirë; Nikolla, Kryepiskop i Japonisë; Simeoni, episkop i parë i Tverit; Romani, princ i Ugliçit; Ansgari, episkop i Hamburgut dhe apostull i Skandinavisë | Epistle: 2 Pjet. 2:9-22 [J.34] | Gospel: Llk. 2:25-38','Fish permitted','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/february.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-02-04','cruce neagră',array[]::text[],'Osh. Isidor Pilusioti; Jasimi; Dësh. Theoktisti; Isidor Pelusioti, oshënar; Nikolla Studiti, oshënar; Abrahami, episkop i Arbilit, hieromartir; Niketa i Pitias, oshënar; Fileasi, episkop i Thmuisit, dhe Filoromusi, martirë; Joani, episkop i Irinupolit; Jasim Mrekullibërësi; Theoktisti, martir; Josifi i Alepos, neomartir; Gjergji, princ i Vladimirit; Kirili i Liqenit të Ri (Novojezersk), oshënar; Avrami dhe Korpi i Peçengës, oshënarë; Evagër Mngbimeli, oshënar','Osh. Isidor Pilusioti; Jasimi; Dësh. Theoktisti; Isidor Pelusioti, oshënar; Nikolla Studiti, oshënar; Abrahami, episkop i Arbilit, hieromartir; Niketa i Pitias, oshënar; Fileasi, episkop i Thmuisit, dhe Filoromusi, martirë; Joani, episkop i Irinupolit; Jasim Mrekullibërësi; Theoktisti, martir; Josifi i Alepos, neomartir; Gjergji, princ i Vladimirit; Kirili i Liqenit të Ri (Novojezersk), oshënar; Avrami dhe Korpi i Peçengës, oshënarë; Evagër Mngbimeli, oshënar | Hahen të gjitha | Epistle: 2 Petr. 3:1-7 | Gospel: Mk. 13:24-31','Hahen të gjitha','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/february.json?v=0.5.536',true),
