('AL','sq','al-orthodox-autocephalous-church','2026-03-12','cruce neagră',array[]::text[],'Omol. Theofani; Grigor Dialogu; Simeoni, Theologu i ri; Theofan Rrëfyesi i Megalo Agros, oshënar; Nëntë Martirët; Finesi, i drejtë; Nikodhimi i Mamolas, oshënar; Pavli, episkop i Leonit','Omol. Theofani; Grigor Dialogu; Simeoni, Theologu i ri; Theofan Rrëfyesi i Megalo Agros, oshënar; Nëntë Martirët; Finesi, i drejtë; Nikodhimi i Mamolas, oshënar; Pavli, episkop i Leonit','Strict fast','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/march.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-03-13','cruce neagră',array[]::text[],'Transf. lips. të sh. Niqiforit; Osh. Geraldi; Niqifori, Patriark i Konstandinopojës; Publi, episkop i Athinës, hieromartir; Afrikani, Publi dhe Terenti, martirë; Kristina, martire','Transf. lips. të sh. Niqiforit; Osh. Geraldi; Niqifori, Patriark i Konstandinopojës; Publi, episkop i Athinës, hieromartir; Afrikani, Publi dhe Terenti, martirë; Kristina, martire | III e Akathistit - Presanctified Liturgy','III e Akathistit - Presanctified Liturgy','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/march.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-03-14','cruce neagră',array[]::text[],'Osh. Benedikti; Ep. Bonifati në Skoci; Mbr/sha. Matilda; Benedikti i Norçias, oshënar; Aleksandri i Pidnas, martir; Efskimon Rrëfyesi, episkop i Lampsakës; Rostislav-Mihaili, princ i Kievit; Theognosti, mitropolit i Kievit, Vladimirit dhe i gjithë Rusisë','Osh. Benedikti; Ep. Bonifati në Skoci; Mbr/sha. Matilda; Benedikti i Norçias, oshënar; Aleksandri i Pidnas, martir; Efskimon Rrëfyesi, episkop i Lampsakës; Rostislav-Mihaili, princ i Kievit; Theognosti, mitropolit i Kievit, Vladimirit dhe i gjithë Rusisë','Oil and wine','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/march.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-03-15','cruce neagră',array[]::text[],'E Dielë e Tretë e Kreshmës (Falja e Kryqit); Ap. Aristovuli i Britanisë; Agapi, Timolau, Paisi, në Qesari, dhe shokët e tyre, martirë; Nikandri në Egjipt, martir; Zaharia, papë i Romës; Manuel Kretasi, neomartir; Nikandri i Gorodnos, oshënar','E Dielë e Tretë e Kreshmës (Falja e Kryqit); Ap. Aristovuli i Britanisë; Agapi, Timolau, Paisi, në Qesari, dhe shokët e tyre, martirë; Nikandri në Egjipt, martir; Zaharia, papë i Romës; Manuel Kretasi, neomartir; Nikandri i Gorodnos, oshënar | Epistle: Heb. 4:14-5:6 | Gospel: Mk. 8:34-9:1','Oil and wine','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/march.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-03-16','cruce neagră',array[]::text[],'Dësh. Savini; Juliani; Osh. Kristodhuli, Anini, çudibërës; Savini i Egjiptit, martir; Papai, martir; Joani i manastirit të Rufinianëve, oshënar; Romani i Parionit, martir; 10 Martirë të Fenikisë; Aleksandri I, papë i Romës, hieromartir; Aninai Çudibërësi, oshënar; Malakia, neomartir; Serapioni, kryepiskop i Novgorodit; Pimeni, i marrë për Krishtin, dhe Andoni nga Messi, oshënarë','Dësh. Savini; Juliani; Osh. Kristodhuli, Anini, çudibërës; Savini i Egjiptit, martir; Papai, martir; Joani i manastirit të Rufinianëve, oshënar; Romani i Parionit, martir; 10 Martirë të Fenikisë; Aleksandri I, papë i Romës, hieromartir; Aninai Çudibërësi, oshënar; Malakia, neomartir; Serapioni, kryepiskop i Novgorodit; Pimeni, i marrë për Krishtin, dhe Andoni nga Messi, oshënarë','Strict fast','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/march.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-03-17','cruce neagră',array[]::text[],'Osh. Aleksi; Ep. Patriku, ndriçues i Irlandës; Osh. Gertruda; Aleksi, Njeriu i Perëndisë, oshënar; Marini, martir; Theosterikt Rrëfyesi, igumen i manastirit të Peleketit, oshënar; Pavli, martir; Makar Çudibërësi, igumen i Koliazinit, oshënar; Gavril Mzire, i Riu, oshënar; Patriku, episkop dhe ndriçues i Irlandës; Gertruda e Niveles','Osh. Aleksi; Ep. Patriku, ndriçues i Irlandës; Osh. Gertruda; Aleksi, Njeriu i Perëndisë, oshënar; Marini, martir; Theosterikt Rrëfyesi, igumen i manastirit të Peleketit, oshënar; Pavli, martir; Makar Çudibërësi, igumen i Koliazinit, oshënar; Gavril Mzire, i Riu, oshënar; Patriku, episkop dhe ndriçues i Irlandës; Gertruda e Niveles','Strict fast','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/march.json?v=0.5.536',true),
