('AL','sq','al-orthodox-autocephalous-church','2026-12-03','cruce neagră',array[]::text[],'Pr. Sofonia; Dësh. Agapi, Selefki; Dësh. i ri Angjeli; Sofonia, profet; Theodhuli i Qipros, i marrë për Krishtin; Theodhul Stiliti, oshënar; Joan Hesikasti, episkop i Kolonisë; Agapi, Selefki dhe Mamasi, martirë; Gavriili, mitropolit i Prusës, neomartir; Angjeli i Hios, neomartir; Sava i Zvenigorodit, oshënar; Gjergji i Cernicës, oshënar','Pr. Sofonia; Dësh. Agapi, Selefki; Dësh. i ri Angjeli; Sofonia, profet; Theodhuli i Qipros, i marrë për Krishtin; Theodhul Stiliti, oshënar; Joan Hesikasti, episkop i Kolonisë; Agapi, Selefki dhe Mamasi, martirë; Gavriili, mitropolit i Prusës, neomartir; Angjeli i Hios, neomartir; Sava i Zvenigorodit, oshënar; Gjergji i Cernicës, oshënar | Epistle: 1 Tim. 6:17-21 | Gospel: Llk. 20:9-18',null,'Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/december.json?v=0.5.536',true),
('AL','sq','al-orthodox-autocephalous-church','2026-12-04','cruce neagră',array[]::text[],'Dësh. Varvara; Osh. Joan Damaskini; Oshd. Kristodhula; Varvara dhe Juliana, martire; Joan Damaskini, oshënar; Joani, episkop i Polibotusit, konfesor; Kristodhuli dhe Kristodhula, martirë; Serafimi, episkop i Fanarit, neomartir; Genadi, kryepiskop i Novgorodit; Guria, kryepiskop i Kazanit','Dësh. Varvara; Osh. Joan Damaskini; Oshd. Kristodhula; Varvara dhe Juliana, martire; Joan Damaskini, oshënar; Joani, episkop i Polibotusit, konfesor; Kristodhuli dhe Kristodhula, martirë; Serafimi, episkop i Fanarit, neomartir; Genadi, kryepiskop i Novgorodit; Guria, kryepiskop i Kazanit | Epistle: Gal. 3:23-29; Gal. 4:1-5 | Gospel: Mk. 5:24-34','Oil and wine','Official Orthodox Autocephalous Church of Albania calendar JSON, https://orthodoxalbania.org/2026/wp-content/plugins/orthodox-calendar/data/december.json?v=0.5.536',true),
